{
  "case_id": "C02",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "As bodies age, some cells stop dividing but refuse to die. These worn-out cells, called senescent cells, build up in our tissues and leak chemical signals that irritate everything around them.",
      "on_screen": "Animation: healthy dividing cells; a few turn grey and stall, giving off signal molecules.",
      "claim_refs": ["SYN-C02:background"]
    },
    {
      "beat": "The experiment",
      "narration": "Researchers tested whether clearing them out helps. Ninety-six mice, aged twenty-four months, got either a drug pair called dasatinib and quercetin or a dummy treatment, three days every fortnight for sixteen weeks. Neither the assessors nor the analyst knew which mice got what.",
      "on_screen": "Two mouse groups split by a randomisation icon; a calendar marking three dosing days every fourteen days; a 'blinded' badge.",
      "claim_refs": ["SYN-C02:abstract", "SYN-C02:methods", "SYN-C02:statistical_analysis"]
    },
    {
      "beat": "What happened",
      "narration": "In treated mice, senescent cells in belly fat fell by forty-one percent. They lasted twenty-two percent longer on a rotating rod, a test of balance and coordination. And their median remaining lifespan rose from about twenty-one weeks to twenty-seven.",
      "on_screen": "Three result cards: -41% senescent cells; +22% rotarod time; 21.4 to 26.9 weeks survival curve.",
      "claim_refs": ["SYN-C02:results.p16_burden", "SYN-C02:results.rotarod", "SYN-C02:results.lifespan"]
    },
    {
      "beat": "The catch",
      "narration": "But grip strength did not improve at all, and only fat tissue was checked, in one strain of mouse at one age. Promising, and worth following up. Not yet a reason to take anything.",
      "on_screen": "Grip-strength card marked 'no change'; caption: one tissue, one strain, one age; mice, not people.",
      "claim_refs": ["SYN-C02:results.grip_strength", "SYN-C02:limitations", "SYN-C02:conclusion"]
    }
  ]
}
